alter table public.crm_guest_requests add column if not exists department text; alter table public.crm_guest_requests add column if not exists started_at timestamptz; alter table public.crm_guest_requests add column if not exists paused_at timestamptz; alter table public.crm_guest_requests add column if not exists resolution text; alter table public.crm_guest_requests add column if not exists rating numeric; alter table public.crm_guest_requests add column if not exists reopened_at timestamptz; alter table public.crm_guest_requests add column if not exists escalation_level integer not null default 0;
alter table public.crm_complaints add column if not exists category text; alter table public.crm_complaints add column if not exists sla_due_at timestamptz; alter table public.crm_complaints add column if not exists csat numeric; alter table public.crm_complaints add column if not exists nps numeric; alter table public.crm_complaints add column if not exists recovery_cost numeric not null default 0; alter table public.crm_complaints add column if not exists recovery_outcome text; alter table public.crm_complaints add column if not exists customer_communication_at timestamptz;
alter table public.crm_service_recovery_cases add column if not exists csat numeric; alter table public.crm_service_recovery_cases add column if not exists nps numeric; alter table public.crm_service_recovery_cases add column if not exists communication_at timestamptz; alter table public.crm_service_recovery_cases add column if not exists recovery_cost numeric not null default 0;
create table if not exists public.crm_guest_relation_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,property_id uuid,customer_id uuid,request_id uuid references public.crm_guest_requests(id) on delete set null,complaint_id uuid references public.crm_complaints(id) on delete set null,recovery_id uuid references public.crm_service_recovery_cases(id) on delete set null,event_type text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.crm_guest_relation_events enable row level security; drop policy if exists crm_guest_relation_events_scope on public.crm_guest_relation_events; create policy crm_guest_relation_events_scope on public.crm_guest_relation_events for all to authenticated using(anaira_can_access_tenant(tenant_id)) with check(anaira_can_access_tenant(tenant_id));
create or replace function public.anaira_complaint_action(p_complaint_id uuid,p_action text,p_resolution text default null,p_csat numeric default null,p_nps numeric default null,p_recovery_cost numeric default null,p_recovery_outcome text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare c public.crm_complaints%rowtype; ns text; begin select * into c from public.crm_complaints where id=p_complaint_id for update; if not found or not anaira_can_access_tenant(c.tenant_id) then raise exception 'Unauthorized or complaint not found'; end if; ns:=case p_action when 'assign' then 'ASSIGNED' when 'investigate' then 'INVESTIGATING' when 'recover' then 'RECOVERY' when 'resolve' then 'RESOLVED' when 'close' then 'CLOSED' when 'reopen' then 'OPEN' else null end; if ns is null then raise exception 'Unsupported complaint action'; end if; update public.crm_complaints set status=ns,resolution=coalesce(p_resolution,resolution),csat=coalesce(p_csat,csat),nps=coalesce(p_nps,nps),recovery_cost=coalesce(p_recovery_cost,recovery_cost),recovery_outcome=coalesce(p_recovery_outcome,recovery_outcome),resolved_at=case when p_action in ('resolve','close') then coalesce(resolved_at,now()) else resolved_at end where id=c.id returning * into c; insert into public.crm_guest_relation_events(tenant_id,property_id,customer_id,complaint_id,event_type,payload) values(c.tenant_id,c.property_id,c.customer_id,c.id,'complaint_'||lower(p_action),jsonb_build_object('status',c.status,'resolution',c.resolution,'csat',c.csat,'nps',c.nps)); insert into public.crm_audit_logs(tenant_id,property_id,action,entity_type,entity_id,after_data) values(c.tenant_id,c.property_id,'complaint_'||p_action,'crm_complaints',c.id,to_jsonb(c)); return jsonb_build_object('ok',true,'complaint_id',c.id,'status',c.status); end $$;
revoke all on function public.anaira_complaint_action(uuid,text,text,numeric,numeric,numeric,text) from public; grant execute on function public.anaira_complaint_action(uuid,text,text,numeric,numeric,numeric,text) to authenticated;
create or replace function public.anaira_service_recovery_action(p_recovery_id uuid,p_action text,p_outcome text default null,p_csat numeric default null,p_nps numeric default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.crm_service_recovery_cases%rowtype; ns text; begin select * into s from public.crm_service_recovery_cases where id=p_recovery_id for update; if not found or not anaira_can_access_tenant(s.tenant_id) then raise exception 'Unauthorized or recovery case not found'; end if; ns:=case p_action when 'approve' then 'APPROVED' when 'start' then 'IN_PROGRESS' when 'complete' then 'COMPLETED' when 'cancel' then 'CANCELLED' else null end; if ns is null then raise exception 'Unsupported recovery action'; end if; update public.crm_service_recovery_cases set status=ns,outcome=coalesce(p_outcome,outcome),csat=coalesce(p_csat,csat),nps=coalesce(p_nps,nps),communication_at=case when p_action='approve' then coalesce(communication_at,now()) else communication_at end,updated_at=now() where id=s.id returning * into s; insert into public.crm_guest_relation_events(tenant_id,property_id,customer_id,recovery_id,event_type,payload) values(s.tenant_id,s.property_id,s.customer_id,s.id,'recovery_'||lower(p_action),jsonb_build_object('status',s.status,'outcome',s.outcome,'csat',s.csat,'nps',s.nps)); insert into public.crm_audit_logs(tenant_id,property_id,action,entity_type,entity_id,after_data) values(s.tenant_id,s.property_id,'service_recovery_'||p_action,'crm_service_recovery_cases',s.id,to_jsonb(s)); return jsonb_build_object('ok',true,'recovery_id',s.id,'status',s.status); end $$;
revoke all on function public.anaira_service_recovery_action(uuid,text,text,numeric,numeric) from public; grant execute on function public.anaira_service_recovery_action(uuid,text,text,numeric,numeric) to authenticated;
create or replace function public.anaira_guest_request_action(p_request_id uuid,p_action text,p_resolution text default null,p_rating numeric default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare r public.crm_guest_requests%rowtype; ns text; begin select * into r from public.crm_guest_requests where id=p_request_id for update; if not found or not anaira_can_access_tenant(r.tenant_id) then raise exception 'Unauthorized or request not found'; end if; ns:=case p_action when 'acknowledge' then 'ACKNOWLEDGED' when 'assign' then 'ASSIGNED' when 'start' then 'IN_PROGRESS' when 'pause' then 'WAITING' when 'escalate' then 'ESCALATED' when 'complete' then 'COMPLETED' when 'reopen' then 'OPEN' when 'cancel' then 'CANCELLED' else null end; if ns is null then raise exception 'Unsupported guest request action'; end if; update public.crm_guest_requests set status=ns,started_at=case when p_action='start' then now() else started_at end,paused_at=case when p_action='pause' then now() else paused_at end,escalated_at=case when p_action='escalate' then now() else escalated_at end,completed_at=case when p_action='complete' then now() else completed_at end,reopened_at=case when p_action='reopen' then now() else reopened_at end,resolution=coalesce(p_resolution,resolution),rating=coalesce(p_rating,rating),escalation_level=case when p_action='escalate' then escalation_level+1 else escalation_level end where id=r.id returning * into r; insert into public.crm_guest_relation_events(tenant_id,property_id,customer_id,request_id,event_type,payload) values(r.tenant_id,r.property_id,r.customer_id,r.id,'request_'||lower(p_action),jsonb_build_object('status',r.status,'resolution',r.resolution,'rating',r.rating)); insert into public.crm_audit_logs(tenant_id,property_id,action,entity_type,entity_id,after_data) values(r.tenant_id,r.property_id,'guest_request_'||p_action,'crm_guest_requests',r.id,to_jsonb(r)); return jsonb_build_object('ok',true,'request_id',r.id,'status',r.status); end $$;
revoke all on function public.anaira_guest_request_action(uuid,text,text,numeric) from public; grant execute on function public.anaira_guest_request_action(uuid,text,text,numeric) to authenticated;
create or replace function public.anaira_guest_request_sla_worker(p_limit integer default 100) returns integer language plpgsql security definer set search_path=public,pg_temp as $$ declare r record; n integer:=0; begin for r in select * from public.crm_guest_requests where status not in ('COMPLETED','CANCELLED') and sla_due_at is not null and sla_due_at<now() and coalesce(sla_status,'')<>'OVERDUE' order by sla_due_at limit p_limit for update skip locked loop update public.crm_guest_requests set sla_status='OVERDUE' where id=r.id; insert into public.crm_guest_relation_events(tenant_id,property_id,customer_id,request_id,event_type,payload) values(r.tenant_id,r.property_id,r.customer_id,r.id,'request_overdue',jsonb_build_object('sla_due_at',r.sla_due_at)); insert into public.crm_audit_logs(tenant_id,property_id,action,entity_type,entity_id,after_data) values(r.tenant_id,r.property_id,'guest_request_overdue','crm_guest_requests',r.id,jsonb_build_object('sla_due_at',r.sla_due_at)); n:=n+1; end loop; return n; end $$;
revoke all on function public.anaira_guest_request_sla_worker(integer) from public; grant execute on function public.anaira_guest_request_sla_worker(integer) to service_role;
